 	const [campaignSending, setCampaignSending] = useState(false);
 	const [campaignStatus, setCampaignStatus] = useState<{
 		type: "success" | "error";
 		text: string;
 	} | null>(null);
 	const [campaignLogs, setCampaignLogs] = useState<
 		Array<{ date: string; subject: string; recipients: number }>
