 				sent?: number;
 				error?: string;
 			};
 			if (!res.ok) {
 				throw new Error(data.error || `Dispatch failed (${res.status})`);
 			}
 			const sent = typeof data.sent === "number" ? data.sent : recipients.length;
 			setCampaignLogs((prev) => [
 				{
