						style={{
							padding: "calc(var(--space-base) / 4) var(--space-base)",
							borderRadius: "var(--radius-pill)",
							borderWidth: "var(--rule-width)",
							borderStyle: "solid",
							borderColor: channels.includes("security")
								? "var(--rule-strong)"
								: "var(--rule)",
							backgroundColor: channels.includes("security")
								? "var(--ink)"
								: "transparent",
							color: channels.includes("security")
								? "var(--ground)"
								: "var(--ink-muted)",
							fontFamily: "var(--font-mono)",
							fontSize: "var(--mono-size)",
							cursor: "pointer",
						}}
					>
						[x] Security & Network Audits
					</button>
				</div>

				<div
					style={{
						display: "flex",
						gap: "var(--space-base)",
						flexWrap: "wrap",
					}}
				>
					<input
						type="email"
						value={email}
						onChange={(e) => setEmail(e.target.value)}
						placeholder="researcher@lab.org"
						required
						style={{
							flex: 1,
							minWidth: "16rem",
							padding: "var(--space-base) var(--gap-sm)",
							borderWidth: "var(--rule-width)",
							borderStyle: "solid",
							borderColor: "var(--rule-strong)",
							backgroundColor: "var(--ground)",
							color: "var(--ink)",
							fontFamily: "var(--font-mono)",
							fontSize: "var(--mono-size)",
							borderRadius: "var(--radius-control)",
							outline: "none",
						}}
					/>
					<button
						type="submit"
						disabled={isSubmitting}
						style={{
							padding: "var(--space-base) var(--gap-md)",
							borderRadius: "var(--radius-pill)",
							backgroundColor: "var(--ink)",
							color: "var(--ground)",
							fontFamily: "var(--font-mono)",
							fontSize: "var(--mono-size)",
							fontWeight: 600,
							border: "none",
							cursor: "pointer",
							textTransform: "uppercase",
							letterSpacing: "0.08em",
						}}
					>
						{isSubmitting ? "Subscribing..." : "Subscribe to Radar ➔"}
					</button>
				</div>
			</form>

			{status && (
				<div
					role="status"
					style={{
						padding: "calc(var(--space-base) / 2) var(--gap-sm)",
						backgroundColor: "var(--ground)",
						borderWidth: "var(--rule-width)",
