import type { ReactNode } from "react";
import { FusedHeadline } from "./FusedHeadline";

type Props = {
	/** Two-digit chapter number, e.g. "02". */
	index: string;
	/** Chapter name, e.g. "THE JOURNEY". */
	eyebrow: string;
	title: { lead: string; cont: string };
	/** One or two sentences setting up everything nested inside. */
	lede: string;
	children: ReactNode;
};

/**
 * One chapter of the homepage's single story: a file's journey from drop to
 * download. The chapter number + eyebrow give every band a place in the
 * narrative, so the page reads as six connected rooms instead of eleven
 * stacked billboards.
 *
 * The `maxWidth` cap sits on a padding-free wrapper: the shell owns the
 * gutter, the band owns only its cap (see `band-gutter.test.ts`). Vertical
 * padding is the band's own rhythm and stays.
 */
export function StoryChapter({ index, eyebrow, title, lede, children }: Props) {
	return (
		<section
			aria-label={`Chapter ${index}: ${eyebrow}`}
			style={{ maxWidth: "var(--max-width)", margin: "0 auto", width: "100%" }}
		>
			<div
				style={{
					display: "flex",
					flexDirection: "column",
					gap: "var(--gap-sm)",
					paddingTop: "var(--gap-md)",
					paddingBottom: "var(--gap-md)",
				}}
			>
				<p className="meta" style={{ color: "var(--accent)", margin: 0 }}>
					CH.{index} {"//"} {eyebrow}
				</p>
				<FusedHeadline as="h2" lead={title.lead} cont={title.cont} />
				<p
					style={{
						color: "var(--ink-muted)",
						fontSize: "var(--body-size)",
						lineHeight: 1.6,
						margin: 0,
						maxWidth: "65ch",
					}}
				>
					{lede}
				</p>
				<div
					style={{
						display: "flex",
						flexDirection: "column",
						gap: "var(--gap-md)",
						marginTop: "var(--space-base)",
					}}
				>
					{children}
				</div>
			</div>
		</section>
	);
}

export type PipelineStage = {
	/** Short mono code painted on the rail, e.g. "ROUTE". */
	code: string;
	title: string;
	body: string;
	/** Names the real module or function that runs this stage. */
	detail: string;
};

type Props = {
	stages: PipelineStage[];
};

/**
 * The journey chapter's spine: every conversion's five stages as a vertical
 * timeline. A 1px rail runs down the left; each stage hangs a node off it --
 * hollow for the stages travelled, solid mint for the delivery at the end.
 * Nodes are geometric glyphs (`○`/`●`), never emoji, per the product's
 * typography-first discipline.
 *
 * Server-rendered from `PIPELINE_STAGES` in `home-content.ts`, whose details
 * name real modules, so the timeline is an index into the codebase as well
 * as a story beat. The cap wrapper carries no padding (shell owns the
 * gutter); the rail's own inset is vertical rhythm, not a gutter.
 */
export function PipelineTimeline({ stages }: Props) {
	if (stages.length === 0) return null;
	const last = stages.length - 1;

	return (
		<ol
			aria-label="Stages of a conversion"
			style={{
				maxWidth: "var(--max-width)",
				margin: "0 auto",
				width: "100%",
				listStyle: "none",
				paddingTop: 0,
				paddingBottom: 0,
				paddingLeft: 0,
				paddingRight: 0,
			}}
		>
			{stages.map((stage, index) => {
				const isLast = index === last;
				return (
					<li
						key={stage.code}
						style={{
							display: "grid",
							gridTemplateColumns: "3.5rem 1fr",
							gap: "var(--gap-sm)",
							position: "relative",
							paddingBottom: isLast ? 0 : "var(--gap-md)",
						}}
					>
						{/* Rail: node glyph over a hairline that stops at the last node. */}
						<div
							aria-hidden="true"
							style={{
								display: "flex",
								flexDirection: "column",
								alignItems: "center",
							}}
						>
							<span
								className="mono"
								style={{
									fontSize: "var(--body-size)",
									lineHeight: 1.4,
									color: isLast ? "var(--accent)" : "var(--ink-muted)",
								}}
							>
								{isLast ? "●" : "○"}
							</span>
							{!isLast && (
								<span
									style={{
										flex: 1,
										minHeight: "var(--gap-sm)",
										borderLeftWidth: "var(--rule-width)",
										borderLeftStyle: "solid",
										borderLeftColor: "var(--rule)",
									}}
								/>
							)}
						</div>

						<div
							style={{
								display: "flex",
								flexDirection: "column",
								gap: "calc(var(--space-base) / 2)",
								paddingBottom: isLast ? 0 : "var(--space-base)",
							}}
						>
							<div
								style={{
									display: "flex",
									alignItems: "baseline",
									gap: "var(--space-base)",
									flexWrap: "wrap",
								}}
							>
								<span
									className="mono"
									style={{
										fontSize: "var(--mono-size)",
										letterSpacing: "0.1em",
										color: isLast ? "var(--accent)" : "var(--ink-muted)",
									}}
								>
									{String(index + 1).padStart(2, "0")} · {stage.code}
								</span>
								<span
									style={{
										fontSize: "var(--body-size)",
										fontWeight: 500,
										color: "var(--ink)",
									}}
								>
									{stage.title}
								</span>
							</div>
							<p
								style={{
									color: "var(--ink-muted)",
									fontSize: "var(--mono-size)",
									lineHeight: 1.6,
									margin: 0,
									maxWidth: "65ch",
								}}
							>
								{stage.body}
							</p>
							<p
								className="mono"
								style={{
									fontSize: "var(--mono-size)",
									color: "var(--rule-strong)",
									margin: 0,
								}}
							>
								{stage.detail}
							</p>
						</div>
					</li>
				);
			})}
		</ol>
	);
}

"use client";

import { useMemo, useState } from "react";
import { findConversionRoute } from "@/core/registry/converter-match";
import { conversionBranches } from "@/core/registry/stats";
import { branchPath } from "./BranchDiagram";

type Props = {
	/** Input extensions worth exploring, richest lineage first. */
	sources: string[];
};

const MAX_DIRECT_SHOWN = 12;
const MAX_TWO_HOP = 6;
const TREE_WIDTH = 240;
const ROW_HEIGHT = 26;

type TwoHop = {
	via: string;
	to: string;
	tools: string;
};

/**
 * The graph chapter's instrument: pick any input format and watch its live
 * lineage branch. Direct edges come from `conversionBranches`; the two-hop
 * chains underneath are found by the real `findConversionRoute` BFS, with
 * the tool chain that the router itself would execute.
 *
 * Everything here is derived from the registry at render time, so the tree
 * can never drift from the product: add a tool, and some format's lineage
 * grows a branch on the next build. The `<svg>` is `aria-hidden` geometry
 * (as in `BranchDiagram`); the format names beside it are the content.
 */
export function LineageExplorer({ sources }: Props) {
	const [active, setActive] = useState(sources[0] ?? "heic");

	const direct = useMemo(() => conversionBranches(active), [active]);
	const shown = direct.slice(0, MAX_DIRECT_SHOWN);
	const hidden = direct.length - shown.length;

	const twoHop = useMemo<TwoHop[]>(() => {
		const out: TwoHop[] = [];
		const directSet = new Set(direct);
		for (const via of direct) {
			if (out.length >= MAX_TWO_HOP) break;
			for (const target of conversionBranches(via)) {
				if (out.length >= MAX_TWO_HOP) break;
				if (target === active || directSet.has(target)) continue;
				if (out.some((chain) => chain.to === target)) continue;
				const route = findConversionRoute(active, target);
				if (!route || route.route.length < 2) continue;
				out.push({
					via,
					to: target,
					tools: route.route.map((tool) => tool.slug ?? tool.id).join(" + "),
				});
			}
		}
		return out;
	}, [active, direct]);

	const treeHeight = Math.max(96, shown.length * ROW_HEIGHT);

	return (
		<div
			className="m3-surface-card flex w-full flex-col gap-[var(--gap-md)] p-[var(--gap-md)]"
			style={{ maxWidth: "var(--max-width)", margin: "0 auto" }}
		>
			<div>
				<span
					className="meta"
					style={{
						color: "var(--accent)",
						fontSize: "var(--mono-size)",
						letterSpacing: "0.1em",
						textTransform: "uppercase",
					}}
				>
					LINEAGE EXPLORER {"//"} LIVE REGISTRY GRAPH
				</span>
				<h3
					style={{
						fontSize: "var(--headline-size)",
						letterSpacing: "var(--headline-tracking)",
						fontWeight: 400,
						margin: "calc(var(--space-base) / 2) 0 0",
						color: "var(--ink)",
					}}
				>
					Pick a format. Watch it branch.
				</h3>
			</div>

			<div
				role="group"
				aria-label="Source format"
				style={{
					display: "flex",
					gap: "calc(var(--space-base) / 2)",
					flexWrap: "wrap",
				}}
			>
				{sources.map((source) => {
					const isSelected = source === active;
					return (
						<button
							key={source}
							type="button"
							onClick={() => setActive(source)}
							aria-pressed={isSelected}
							className={`m3-chip ${isSelected ? "m3-chip-active" : ""}`}
						>
							{source.toUpperCase()}
						</button>
					);
				})}
			</div>

			<div
				style={{
					display: "flex",
					alignItems: "center",
					gap: "var(--gap-sm)",
					flexWrap: "wrap",
				}}
			>
				<span className="meta" style={{ color: "var(--ink)" }}>
					{active.toUpperCase()}
				</span>
				<svg
					aria-hidden="true"
					width={TREE_WIDTH}
					height={treeHeight}
					viewBox={`0 0 ${TREE_WIDTH} ${treeHeight}`}
					style={{ flexShrink: 0, overflow: "visible" }}
				>
					{shown.map((output, index) => (
						<path
							key={output}
							d={branchPath(index, shown.length, TREE_WIDTH, treeHeight)}
							stroke="var(--rule)"
							strokeWidth="1"
							fill="none"
						/>
					))}
				</svg>
				<div
					style={{
						display: "flex",
						flexDirection: "column",
						justifyContent: "space-around",
						height: `${treeHeight}px`,
					}}
				>
					{shown.map((output) => (
						<span
							key={output}
							className="meta"
							style={{ color: "var(--ink-muted)" }}
						>
							{output.toUpperCase()}
						</span>
					))}
				</div>
				<span
					className="mono"
					style={{ fontSize: "var(--mono-size)", color: "var(--accent)" }}
				>
					{direct.length} DIRECT {direct.length === 1 ? "EDGE" : "EDGES"}
					{hidden > 0 ? ` · +${hidden} MORE` : ""}
				</span>
			</div>

			<div
				style={{
					borderTopWidth: "var(--rule-width)",
					borderTopStyle: "solid",
					borderTopColor: "var(--rule)",
					paddingTop: "var(--space-base)",
					display: "flex",
					flexDirection: "column",
					gap: "calc(var(--space-base) / 2)",
				}}
			>
				<span
					className="meta"
					style={{ color: "var(--accent)", fontSize: "var(--mono-size)" }}
				>
					TWO-HOP LINEAGE — ROUTES THE ENGINE FOUND
				</span>
				{twoHop.length === 0 ? (
					<p
						style={{
							fontSize: "var(--mono-size)",
							color: "var(--ink-muted)",
							margin: 0,
						}}
					>
						Every reachable format from {active.toUpperCase()} is one hop
						away. Pick a richer source to watch the router chain tools.
					</p>
				) : (
					twoHop.map((chain) => (
						<div
							key={`${chain.via}-${chain.to}`}
							className="mono"
							style={{
								fontSize: "var(--mono-size)",
								color: "var(--ink-muted)",
								display: "flex",
								gap: "var(--space-base)",
								flexWrap: "wrap",
								alignItems: "baseline",
							}}
						>
							<span style={{ color: "var(--ink)" }}>
								{active.toUpperCase()} ➔ {chain.via.toUpperCase()} ➔{" "}
								{chain.to.toUpperCase()}
							</span>
							<span style={{ color: "var(--rule-strong)" }}>{chain.tools}</span>
						</div>
					))
				)}
			</div>
		</div>
	);
}

