-				>
-					Pick a format. Watch it branch.
-				</h3>
-			</div>
+			<CardHeader
+				eyebrow="LINEAGE EXPLORER // LIVE REGISTRY GRAPH"
+				title="Pick a format. Watch it branch."
+			/>

 			<fieldset
 				style={{
 					display: "flex",
 					gap: "calc(var(--space-base) / 2)",
