 */
.m3-surface-card {
	background-color: var(--surface);
	border: 1px solid var(--rule-subtle);
	border-radius: 16px;
	transition: border-color var(--dur-fade) var(--ease);
}

.m3-surface-card:hover {
	border-color: var(--rule);
}

.m3-pill {
	border-radius: var(--radius-pill);
}

.m3-icon-btn {
	width: 32px;
	height: 32px;
	border-radius: var(--radius-pill);
	display: inline-flex;
	align-items: center;
	justify-content: center;
	border: 1px solid transparent;
	background: transparent;
	color: var(--ink-muted);
	cursor: pointer;
	transition: all var(--dur-fade) var(--ease);
}

.m3-icon-btn:hover {
	background-color: var(--surface);
	color: var(--ink);
	border-color: var(--rule-subtle);
}

.m3-icon-btn-active {
	background-color: var(--surface);
	color: var(--accent);
	border-color: var(--accent);
}

.m3-segmented {
	display: inline-flex;
	align-items: center;
	border-radius: var(--radius-pill);
	background: var(--surface);
	border: 1px solid var(--rule);
	padding: 2px;
	gap: 2px;
}

.m3-segmented-btn {
	border-radius: var(--radius-pill);
	padding: 4px 10px;
	font-size: 10px;
	font-family: var(--font-mono);
	border: 1px solid transparent;
	background: transparent;
	color: var(--ink-muted);
	cursor: pointer;
	transition: all var(--dur-fade) var(--ease);
	white-space: nowrap;
}

.m3-segmented-btn:hover {
	color: var(--ink);
}

.m3-segmented-btn-active {
	background: var(--ground);
	color: var(--accent);
	border-color: var(--rule-subtle);
	font-weight: 600;
}

.m3-chip {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	border-radius: var(--radius-pill);
	border: 1px solid var(--rule-subtle);
	background: var(--surface);
	color: var(--ink);
	font-family: var(--font-mono);
	font-size: 11px;
	padding: 4px 12px;
	transition: all var(--dur-fade) var(--ease);
	cursor: pointer;
	user-select: none;
}

.m3-chip:hover {
	border-color: var(--rule);
	background: var(--rule-subtle);
}

.m3-chip-active {
	background: var(--accent);
	color: var(--ground);
	border-color: var(--accent);
	font-weight: 600;
}

