import type { ReactNode } from "react";

type Props = {
	/** Mono uppercase eyebrow, e.g. "DISPATCH // STAY SYNCHRONIZED". */
	eyebrow: string;
	/** Plain ink headline. Single colour by design -- emphasis here comes
	 * from the eyebrow above and the lede below, not from a fused clause. */
	title: string;
	/** Optional muted lede paragraph under the header row. */
	lede?: string;
	/** Optional right-side pill (badge, status, install CTA). */
	badge?: ReactNode;
	/** The extension card's outer header is an h2; everything else is h3. */
	headingLevel?: "h2" | "h3";
	/** The manifesto's lede runs to the converter measure; the default is
	 * the 65ch reading measure every other card uses. */
	wideLede?: boolean;
};

/**
 * The canonical card header: eyebrow + headline left, badge right, lede
 * below. Five cards and one explorer re-implemented this shape by hand with
 * small drifts (letter-spacing 0.1em vs 0.08em, badge ink vs accent), so it
 * lives here now -- one spelling, composed everywhere.
 *
 * No width cap and no outer padding: hosts (surface cards, chapter bodies)
 * own their geometry; this owns only the header's internal rhythm.
 */
export function CardHeader({
	eyebrow,
	title,
	lede,
	badge,
	headingLevel = "h3",
	wideLede = false,
}: Props) {
	const Title = headingLevel;
	return (
		<div>
			<div
				style={{
					display: "flex",
					justifyContent: "space-between",
					alignItems: "flex-start",
					flexWrap: "wrap",
					gap: "var(--space-base)",
				}}
			>
				<div>
					<span
						className="meta"
						style={{
							color: "var(--accent)",
							fontSize: "var(--mono-size)",
							letterSpacing: "0.1em",
							textTransform: "uppercase",
						}}
					>
						{eyebrow}
					</span>
					<Title
						style={{
							fontSize: "var(--headline-size)",
							letterSpacing: "var(--headline-tracking)",
							fontWeight: 400,
							margin: "calc(var(--space-base) / 2) 0 0",
							color: "var(--ink)",
						}}
					>
						{title}
					</Title>
				</div>
				{badge}
			</div>
			{lede && (
				<p
					style={{
						color: "var(--ink-muted)",
						fontSize: "var(--body-size)",
						lineHeight: 1.6,
						margin: "var(--space-base) 0 0",
						maxWidth: wideLede ? "var(--converter-width)" : "65ch",
					}}
				>
					{lede}
				</p>
			)}
		</div>
	);
}

type Props = {
	type: "success" | "error";
	text: string;
	/** Label for the dismiss button. Canonical is "[close]". */
	onDismiss: () => void;
};

/**
 * The canonical form-status feedback box: bordered notice with the message
 * left and a dismiss control right. Success draws its border in mint, error
 * in the strong rule -- the same border-means-state language as
 * `ComplianceRow`'s status pill.
 *
 * A plain component with no "use client" directive: its hosts are client
 * components, so it ships in their bundle either way, and staying directive-
 * free keeps the server-component guard green.
 */
export function StatusNotice({ type, text, onDismiss }: Props) {
	return (
		<div
			role="status"
			style={{
				padding: "calc(var(--space-base) / 2) var(--gap-sm)",
				backgroundColor: "var(--surface)",
				borderWidth: "var(--rule-width)",
				borderStyle: "solid",
				borderColor:
					type === "success" ? "var(--accent)" : "var(--rule-strong)",
				color:
					type === "success" ? "var(--accent)" : "var(--ink-muted)",
				fontFamily: "var(--font-mono)",
				fontSize: "var(--mono-size)",
				display: "flex",
				justifyContent: "space-between",
				alignItems: "center",
				gap: "var(--space-base)",
			}}
		>
			<span>{text}</span>
			<button
				type="button"
				onClick={onDismiss}
				style={{
					background: "transparent",
					border: "none",
					color: "var(--ink-muted)",
					cursor: "pointer",
					fontFamily: "var(--font-mono)",
					fontSize: "var(--mono-size)",
					flexShrink: 0,
				}}
			>
				[close]
			</button>
		</div>
	);
}

"use client";

import { useState } from "react";
import { CardHeader } from "@/design/families/CardHeader";
import { StatusNotice } from "@/design/families/StatusNotice";
import {
	type Subscriber,
	type SubscriptionChannel,
	subscribeUser,
	syncSubscriptionRemote,
} from "@/lib/subscriptions";

export type SubscribeChip = {
	value: SubscriptionChannel;
	label: string;
};

type Props = {
	/** Card header copy. */
	eyebrow: string;
	title: string;
	lede: string;
	/** Pre-selected channels; at least one always stays selected. */
	defaultChannels: SubscriptionChannel[];
	/** Persistence source recorded with the subscription. */
	source: Subscriber["source"];
	/** Toggleable channel chips. */
	chips: SubscribeChip[];
	emailPlaceholder: string;
	submitLabel: string;
	/** Fired after a successful subscribe so hosts can refresh counters. */
	onSubscribed?: () => void;
};

/**
 * The canonical subscribe block: header, channel chips, email row, status
 * feedback. `EcosystemRadarCard` and `ExtensionWaitlistCard` each owned a
 * near-verbatim copy of this state machine (email, channels with keep-one
 * minimum, submit-then-sync, dismissible status) -- two copies of the submit
 * path meant every API change had to land twice. Hosts keep only what is
 * actually theirs: defaults, source, chip labels, and surrounding content.
 */
export function SubscribeForm({
	eyebrow,
	title,
	lede,
	defaultChannels,
	source,
	chips,
	emailPlaceholder,
	submitLabel,
	onSubscribed,
}: Props) {
	const [email, setEmail] = useState("");
	const [channels, setChannels] =
		useState<SubscriptionChannel[]>(defaultChannels);
	const [status, setStatus] = useState<{
		text: string;
		type: "success" | "error";
	} | null>(null);
	const [isSubmitting, setIsSubmitting] = useState(false);

	const toggleChannel = (ch: SubscriptionChannel) => {
		if (channels.includes(ch)) {
			if (channels.length > 1) {
				setChannels(channels.filter((c) => c !== ch));
			}
		} else {
			setChannels([...channels, ch]);
		}
	};

	const handleSubmit = (e: React.FormEvent) => {
		e.preventDefault();
		if (!email.trim()) return;
		setIsSubmitting(true);
		const result = subscribeUser(email, channels, source);
		const submittedEmail = email.trim();

		if (result.success) {
			setStatus({ text: result.message, type: "success" });
			setEmail("");
			onSubscribed?.();
			// Fire-and-forget welcome email + Audience sync; local state stays
			// authoritative.
			void syncSubscriptionRemote(submittedEmail, channels, source).then(
				(emailed) => {
					if (emailed) {
						setStatus({
							text: "Subscribed. Check your inbox for a confirmation email.",
							type: "success",
						});
					}
				},
			);
		} else {
			setStatus({ text: result.message, type: "error" });
		}
		setIsSubmitting(false);
	};

	return (
		<div
			style={{
				display: "flex",
				flexDirection: "column",
				gap: "var(--gap-sm)",
			}}
		>
			<CardHeader eyebrow={eyebrow} title={title} lede={lede} />

			<form
				onSubmit={handleSubmit}
				style={{
					display: "flex",
					flexDirection: "column",
					gap: "var(--space-base)",
				}}
			>
				<div
					role="group"
					aria-label="Subscription channels"
					style={{
						display: "flex",
						gap: "calc(var(--space-base) / 2)",
						flexWrap: "wrap",
					}}
				>
					{chips.map((chip) => {
						const isSelected = channels.includes(chip.value);
						return (
							<button
								key={chip.value}
								type="button"
								onClick={() => toggleChannel(chip.value)}
								aria-pressed={isSelected}
								className={`m3-chip ${isSelected ? "m3-chip-active" : ""}`}
							>
								[x] {chip.label}
							</button>
						);
					})}
				</div>

				<div
					style={{
						display: "flex",
						gap: "var(--space-base)",
						flexWrap: "wrap",
					}}
				>
					<input
						type="email"
						value={email}
						onChange={(e) => setEmail(e.target.value)}
						placeholder={emailPlaceholder}
						required
						aria-label="Email address"
						className="mono rounded-full border px-[var(--gap-sm)] py-[var(--space-base)] text-[var(--mono-size)] outline-none transition-colors focus:border-[var(--accent)]"
						style={{
							flex: 1,
							minWidth: "16rem",
							borderColor: "var(--rule-strong)",
							backgroundColor: "var(--surface)",
							color: "var(--ink)",
						}}
					/>
					<button
						type="submit"
						disabled={isSubmitting}
						className="mono border border-transparent px-[var(--gap-md)] py-[var(--space-base)] text-[var(--mono-size)] font-semibold rounded-full uppercase tracking-[0.08em] transition-all hover:bg-[var(--accent)] hover:text-[var(--ground)]"
						style={{
							backgroundColor: "var(--ink)",
							color: "var(--ground)",
							cursor: "pointer",
						}}
					>
						{isSubmitting ? "Subscribing..." : submitLabel}
					</button>
				</div>
			</form>

			{status && (
				<StatusNotice
					type={status.type}
					text={status.text}
					onDismiss={() => setStatus(null)}
				/>
			)}
		</div>
	);
}

