import Link from "next/link";
import type { ReactNode } from "react";

type Props = {
	href: string;
	children: ReactNode;
	/** Fill is the primary call to action; outline is secondary, never primary. */
	variant: "fill" | "outline";
	/** Compact 36px height for in-card CTAs; default 44px v2 pill. */
	size?: "md" | "sm";
	external?: boolean;
};

/**
 * The canonical pill CTA. `HeroBand`'s white primary + transparent secondary
 * pair and the extension card's store button were three copies of the same
 * geometry (pill radius, label tracking, ink fill vs rule outline) with
 * small drifts (44px vs 36px heights kept here as explicit sizes).
 *
 * The fill carries `data-cta-fill`: the global `:focus-visible` ring is
 * `1px solid var(--ink)` -- exactly the fill's own colour -- so the rule in
 * `families.css` pulls the ring inside and recolours it `--ground`, keeping
 * the indicator legible as an indicator rather than part of the pill.
 */
export function PillLink({ href, children, variant, size = "md", external = false }: Props) {
	return (
		<Link
			href={href}
			target={external ? "_blank" : undefined}
			rel={external ? "noopener noreferrer" : undefined}
			{...(variant === "fill" ? { "data-cta-fill": true } : {})}
			style={{
				height: size === "sm" ? "36px" : "44px",
				borderRadius: "var(--radius-pill)",
				display: "inline-flex",
				alignItems: "center",
				gap: "var(--space-base)",
				padding: "0 var(--gap-md)",
				fontSize: "var(--label-size)",
				fontWeight: 500,
				letterSpacing: "var(--label-tracking)",
				textDecoration: "none",
				background: variant === "fill" ? "var(--ink)" : "transparent",
				color: variant === "fill" ? "var(--ground)" : "var(--ink)",
				borderWidth: "var(--rule-width)",
				borderStyle: "solid",
				borderColor:
					variant === "fill" ? "var(--ink)" : "var(--rule)",
			}}
		>
			{children}
		</Link>
	);
}

"use client";

import { useEffect, useRef, useState } from "react";

type Props = {
	/** Final value. Rendered locale-formatted (e.g. 1424 -> "1,424"). */
	end: number;
	/** Animation length. The system's motion stays in the 0.2-1.2s band. */
	durationMs?: number;
	className?: string;
};

/**
 * A number that counts up to its final value on mount -- the honest way to
 * present a live registry or subscriber count, which is computed at render
 * time rather than typed by hand.
 *
 * Original implementation (no third-party animation dependency): a single
 * requestAnimationFrame loop with an ease-out curve. Reduced motion renders
 * the final value immediately with no loop at all. The formatted value is
 * always in the DOM, so static export, no-JS, and assistive technology all
 * get the number, never a "0" placeholder.
 */
export function CountUp({ end, durationMs = 900, className }: Props) {
	const [display, setDisplay] = useState(() =>
		typeof window !== "undefined" &&
		typeof window.matchMedia !== "undefined" &&
		window.matchMedia("(prefers-reduced-motion: reduce)").matches
			? end
			: 0,
	);
	const frame = useRef(0);

	useEffect(() => {
		if (
			typeof window !== "undefined" &&
			typeof window.matchMedia !== "undefined" &&
			window.matchMedia("(prefers-reduced-motion: reduce)").matches
		) {
			setDisplay(end);
			return;
		}
		if (end <= 0 || durationMs <= 0) {
			setDisplay(end);
			return;
		}
		const start = performance.now();
		const tick = (now: number) => {
			const progress = Math.min((now - start) / durationMs, 1);
			const eased = 1 - (1 - progress) ** 3;
			setDisplay(Math.round(eased * end));
			if (progress < 1) frame.current = requestAnimationFrame(tick);
		};
		frame.current = requestAnimationFrame(tick);
		return () => cancelAnimationFrame(frame.current);
	}, [end, durationMs]);

	return (
		<span className={className} aria-label={String(end)}>
			{display.toLocaleString("en-US")}
		</span>
	);
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

type Props = {
	children: ReactNode;
	/** Stagger offset for sequenced reveals within a chapter. */
	delayMs?: number;
	className?: string;
};

/**
 * Scroll-triggered slide-fade for story sections -- the page's chapters
 * resolve as they enter the viewport instead of arriving all at once.
 *
 * Original implementation (no third-party animation dependency): one
 * IntersectionObserver per mount, unobserved after the first reveal. The
 * hidden state is applied from the effect, never at server render, so
 * static export, no-JS crawlers, and first paint all see full content --
 * hiding is strictly a runtime enhancement. Motion is the system's own
 * slide-fade (`--dur-fade`/`--ease` in `primitives.css`), and the universal
 * reduced-motion collapse in `globals.css` covers the transition with no
 * extra handling here.
 */
export function ScrollReveal({ children, delayMs = 0, className }: Props) {
	const ref = useRef<HTMLDivElement>(null);
	const [visible, setVisible] = useState(false);

	useEffect(() => {
		const el = ref.current;
		if (!el) return;
		el.setAttribute("data-scroll-reveal", "");
		if (delayMs > 0) el.style.transitionDelay = `${delayMs}ms`;
		if (typeof IntersectionObserver === "undefined") {
			setVisible(true);
			return;
		}
		const observer = new IntersectionObserver(
			(entries) => {
				for (const entry of entries) {
					if (entry.isIntersecting) {
						setVisible(true);
						observer.disconnect();
					}
				}
			},
			{ threshold: 0.12 },
		);
		observer.observe(el);
		return () => observer.disconnect();
	}, [delayMs]);

	return (
		<div
			ref={ref}
			className={className}
			{...(visible ? { "data-visible": true } : {})}
		>
			{children}
		</div>
	);
}

