import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { CardHeader } from "@/design/families/CardHeader";

describe("CardHeader", () => {
	it("renders eyebrow, title, and lede", () => {
		render(
			<CardHeader
				eyebrow="DISPATCH // STAY SYNCHRONIZED"
				title="The convrtr Ecosystem Radar"
				lede="Subscribe for alerts."
			/>,
		);
		expect(screen.getByText("DISPATCH // STAY SYNCHRONIZED")).toBeDefined();
		expect(screen.getByText("The convrtr Ecosystem Radar")).toBeDefined();
		expect(screen.getByText("Subscribe for alerts.")).toBeDefined();
	});

	it("defaults to h3 and honours an h2 override", () => {
		const { rerender } = render(
			<CardHeader eyebrow="E" title="T" />,
		);
		expect(screen.getByRole("heading", { level: 3 })).toBeDefined();
		rerender(<CardHeader eyebrow="E" title="T" headingLevel="h2" />);
		expect(screen.getByRole("heading", { level: 2 })).toBeDefined();
	});

	it("renders the badge when given", () => {
		render(
			<CardHeader
				eyebrow="E"
				title="T"
				badge={<span data-testid="badge">LIVE</span>}
			/>,
		);
		expect(screen.getByTestId("badge")).toBeDefined();
	});

	it("omits the lede when none is given", () => {
		const { container } = render(<CardHeader eyebrow="E" title="T" />);
		expect(container.querySelectorAll("p").length).toBe(0);
	});
});

import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { StatusNotice } from "@/design/families/StatusNotice";

describe("StatusNotice", () => {
	it("announces the message as a status", () => {
		render(
			<StatusNotice type="success" text="Subscribed." onDismiss={() => {}} />,
		);
		expect(screen.getByRole("status").textContent).toContain("Subscribed.");
	});

	it("paints success in mint and error in the strong rule", () => {
		const { rerender } = render(
			<StatusNotice type="success" text="Ok." onDismiss={() => {}} />,
		);
		const box = screen.getByRole("status");
		expect(box.style.borderColor).toBe("var(--accent)");
		rerender(<StatusNotice type="error" text="Bad." onDismiss={() => {}} />);
		expect(screen.getByRole("status").style.borderColor).toBe(
			"var(--rule-strong)",
		);
	});

	it("dismisses on [close]", () => {
		const onDismiss = vi.fn();
		render(<StatusNotice type="error" text="Bad." onDismiss={onDismiss} />);
		fireEvent.click(screen.getByRole("button", { name: "[close]" }));
		expect(onDismiss).toHaveBeenCalledOnce();
	});
});

import Link from "next/link";
import { render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

vi.mock("next/link", () => ({
	default: ({
		href,
		children,
		...rest
	}: {
		href: string;
		children: React.ReactNode;
	}) => (
		<Link href={href} {...rest}>
			{children}
		</Link>
	),
}));

import { PillLink } from "@/design/primitives/PillLink";

describe("PillLink", () => {
	it("fills the primary pill in ink on ground", () => {
		render(
			<PillLink href="/convert" variant="fill">
				Start converting
			</PillLink>,
		);
		const pill = screen.getByRole("link", { name: "Start converting" });
		expect(pill.style.background).toBe("var(--ink)");
		expect(pill.style.color).toBe("var(--ground)");
		expect(pill.style.borderRadius).toBe("var(--radius-pill)");
		expect(pill.style.height).toBe("44px");
	});

	it("outlines the secondary pill in the rule token", () => {
		render(
			<PillLink href="/blog" variant="outline">
				Read the blog
			</PillLink>,
		);
		const pill = screen.getByRole("link", { name: "Read the blog" });
		expect(pill.style.background).toBe("transparent");
		expect(pill.style.borderWidth).toBe("var(--rule-width)");
		expect(pill.style.borderStyle).toBe("solid");
		expect(pill.style.borderColor).toBe("var(--rule)");
	});

	it("opens externally with opener protection when asked", () => {
		render(
			<PillLink href="https://example.com" variant="fill" size="sm" external>
				Store
			</PillLink>,
		);
		const pill = screen.getByRole("link", { name: "Store" });
		expect(pill.getAttribute("target")).toBe("_blank");
		expect(pill.getAttribute("rel")).toBe("noopener noreferrer");
		expect(pill.style.height).toBe("36px");
	});
});

