+		"matchMedia",
+		vi.fn(() => ({
+			matches: wide,
+			media: "(min-width: 1100px)",
+			addEventListener: vi.fn(),
+			removeEventListener: vi.fn(),
+		})),
+	);
+}
+
+afterEach(() => {
+	vi.unstubAllGlobals();
+	vi.restoreAllMocks();
+});
+
