+	eyebrow: "BEGIN // NO SIGN-UP",
+	title: {
+		lead: "Done reading.",
+		cont: "Start converting.",
+	},
+	lede: "The tab is already open. The engine is already loaded. Your files are still yours.",
+};
+
 export const HOME = {
 	hero: HERO_PROPS,
+	stats: STATS,
+	categoryCards: CATEGORY_CARDS,
+	faq: FAQ_ITEMS,
