							paddingRight: 0,
							display: "flex",
							flexDirection: "column",
							gap: "calc(var(--space-base) / 2)",
							borderTopWidth: "var(--rule-width)",
							borderTopStyle: "solid",
							borderTopColor: "var(--rule-subtle)",
							paddingTop: "var(--space-base)",
							marginTop: "calc(var(--space-base) / 2)",
