						ALL {card.label.toUpperCase()} TOOLS ➔
					</Link>
				</article>
			))}
		</div>
	);
}

import { CHROME_EXTENSION_URL } from "@/lib/site";
import { PillLink } from "@/design/primitives/PillLink";

const INCLUDED = [
	"Every tool included",
	"No file-size paywall",
	"No queue -- 0ms start",
	"Nothing retained, ever",
];

const CLOUD_TOLL = [
	"$19/mo paywall at 50-100MB",
	"30s-15m queues on shared servers",
	"Files retained for hours or days",
	"Upload everything first, hope second",
];

/**
 * The pricing section with one row instead of three tiers: $0 covers
 * everything because a static site has no server bill to pass on. The
 * right column is the cloud toll from the manifesto's own numbers
 * ($19/mo, 30s-15m queues, hours-long retention) -- the comparison a
 * pricing table exists to make, without inventing plans nobody sells.
 *
 * Capped with no horizontal padding of its own: the shell owns the gutter,
 * the band owns only its cap.
 */
export function FreeForeverBand() {
	return (
		<div
			style={{
				maxWidth: "var(--max-width)",
				margin: "0 auto",
				width: "100%",
				display: "grid",
				gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
				gap: "var(--space-base)",
			}}
		>
			<div
				className="m3-surface-card flex flex-col gap-[var(--gap-sm)] p-[var(--gap-md)]"
				style={{
					backgroundColor: "var(--ground)",
					borderColor: "var(--accent)",
				}}
			>
				<span
					className="meta"
					style={{ color: "var(--accent)", fontSize: "var(--mono-size)" }}
				>
					THE ONLY PLAN
				</span>
				<p
					className="mono"
					style={{
						fontSize: "var(--headline-size)",
						color: "var(--ink)",
						margin: 0,
					}}
				>
					$0{" "}
					<span style={{ fontSize: "var(--body-size)", color: "var(--ink-muted)" }}>
						/ forever
					</span>
				</p>
				<ul
					style={{
						listStyle: "none",
						margin: 0,
						paddingLeft: 0,
						paddingRight: 0,
						display: "flex",
						flexDirection: "column",
						gap: "calc(var(--space-base) / 2)",
					}}
				>
					{INCLUDED.map((row) => (
						<li
							key={row}
							className="mono"
							style={{ fontSize: "var(--mono-size)", color: "var(--ink)" }}
						>
							<span style={{ color: "var(--accent)" }}>{"✓ "}</span>
							{row}
						</li>
					))}
				</ul>
				<div
					style={{
						display: "flex",
						gap: "var(--space-base)",
						flexWrap: "wrap",
						marginTop: "var(--space-base)",
					}}
				>
					<PillLink href="/convert" variant="fill" size="sm">
						Start converting
					</PillLink>
					<PillLink
						href={CHROME_EXTENSION_URL}
						variant="outline"
						size="sm"
						external
					>
						Get the extension
					</PillLink>
				</div>
			</div>

			<div
				className="m3-surface-card flex flex-col gap-[var(--gap-sm)] p-[var(--gap-md)]"
				style={{ backgroundColor: "var(--ground)" }}
			>
				<span
					className="meta"
					style={{
						color: "var(--ink-muted)",
						fontSize: "var(--mono-size)",
					}}
				>
					THE CLOUD TOLL
				</span>
				<p
					className="mono"
					style={{
						fontSize: "var(--headline-size)",
						color: "var(--ink-muted)",
						margin: 0,
					}}
				>
					$19{" "}
					<span style={{ fontSize: "var(--body-size)" }}>/ month</span>
				</p>
				<ul
					style={{
						listStyle: "none",
						margin: 0,
						paddingLeft: 0,
						paddingRight: 0,
						display: "flex",
						flexDirection: "column",
						gap: "calc(var(--space-base) / 2)",
					}}
				>
					{CLOUD_TOLL.map((row) => (
						<li
							key={row}
							className="mono"
							style={{
								fontSize: "var(--mono-size)",
								color: "var(--ink-muted)",
							}}
						>
							<span style={{ color: "var(--rule-strong)" }}>{"— "}</span>
							{row}
						</li>
					))}
				</ul>
				<p
					className="mono"
					style={{
						fontSize: "var(--mono-size)",
						color: "var(--rule-strong)",
						margin: "var(--space-base) 0 0",
					}}
				>
					Per the manifesto above. Per their pricing pages.
				</p>
			</div>
		</div>
	);
}

import { CollapsibleSection } from "./CollapsibleSection";

type Props = {
	items: { question: string; answer: string }[];
};

/**
 * Asked constantly, answered without a sales team. Each answer states a
 * checkable fact (network guard, static export, service worker, registry)
 * rather than a reassurance. The first answer ships open; the rest disclose
 * on demand via the shared `CollapsibleSection`.
 *
 * Capped with no horizontal padding of its own: the shell owns the gutter,
 * the band owns only its cap.
 */
export function FaqBand({ items }: Props) {
	if (items.length === 0) return null;
	return (
		<div
			style={{
				maxWidth: "var(--max-width)",
				margin: "0 auto",
				width: "100%",
				display: "flex",
				flexDirection: "column",
				gap: "var(--space-base)",
			}}
		>
			{items.map((item, index) => (
				<CollapsibleSection
					key={item.question}
					heading={item.question}
					defaultOpen={index === 0}
				>
					<p
						style={{
							color: "var(--ink-muted)",
							fontSize: "var(--body-size)",
							lineHeight: 1.6,
							margin: 0,
							maxWidth: "65ch",
							padding: "var(--space-base) var(--gap-sm)",
						}}
					>
						{item.answer}
					</p>
				</CollapsibleSection>
			))}
		</div>
	);
}

import { CHROME_EXTENSION_URL } from "@/lib/site";
import { FusedHeadline } from "./FusedHeadline";
import { PillLink } from "@/design/primitives/PillLink";

type Props = {
	eyebrow: string;
	title: { lead: string; cont: string };
	lede: string;
};

/**
 * The closing call to action: one last headline, both doors in. Converting
 * starts in the tab with no sign-up; the extension moves the same engine
 * beside every tab. Nothing here asks for anything -- there is nothing to
 * give.
 *
 * Capped with no horizontal padding of its own: the shell owns the gutter,
 * the band owns only its cap.
 */
export function FinalCta({ eyebrow, title, lede }: Props) {
	return (
		<div
			style={{
				maxWidth: "var(--max-width)",
				margin: "0 auto",
				width: "100%",
				display: "flex",
				flexDirection: "column",
				gap: "var(--gap-sm)",
				borderTopWidth: "var(--rule-width)",
				borderTopStyle: "solid",
				borderTopColor: "var(--rule)",
				paddingTop: "var(--gap-md)",
			}}
		>
			<p className="meta" style={{ color: "var(--accent)", margin: 0 }}>
				{eyebrow}
			</p>
			<FusedHeadline as="h2" lead={title.lead} cont={title.cont} />
			<p
				style={{
					color: "var(--ink-muted)",
					fontSize: "var(--body-size)",
					lineHeight: 1.6,
					margin: 0,
					maxWidth: "65ch",
				}}
			>
				{lede}
			</p>
			<div
				style={{
					display: "flex",
					gap: "var(--space-base)",
					flexWrap: "wrap",
					marginTop: "var(--space-base)",
				}}
			>
				<PillLink href="/convert" variant="fill">
					Start converting
				</PillLink>
				<PillLink href={CHROME_EXTENSION_URL} variant="outline" external>
					Install the extension ↗
				</PillLink>
			</div>
		</div>
	);
}

