 export function buildWebPageJsonLd({
 	title,
 	description,
 	url,
 	breadcrumbs = [],
 	type = "WebPage",
 }: {
 	title: string;
 	description: string;
 	url: string;
 	breadcrumbs?: { name: string; url?: string }[];
 	type?: string;
 }) {
 	const origin = getOrigin(url);
 	const graph: Record<string, unknown>[] = [
 		{
 			"@type": type,
 			"@id": `${url}/#webpage`,
 			url,
 			name: title,
 			description,
 		},
 	];

 	if (breadcrumbs.length > 0) {
 		graph.push({
 			"@type": "BreadcrumbList",
 			itemListElement: [
 				{
 					"@type": "ListItem",
 					position: 1,
 					name: "Home",
 					item: origin,
 				},
 				...breadcrumbs.map((crumb, idx) => ({
 					"@type": "ListItem",
 					position: idx + 2,
 					name: crumb.name,
 					...(crumb.url ? { item: crumb.url } : {}),
 				})),
 			],
 		});
 	}

 	return {
 		"@context": "https://schema.org",
