 			}}
 		>
 			<div
 				style={{
 					display: "flex",
+					justifyContent:"center",
 					alignItems: "center",
 					gap: "var(--space-base)",
+					rowGap: "calc(var(--space-base) / 2)",
 					flexWrap: "wrap",
 					flex: 1,
+					minWidth: 0,
 				}}
 			>
 				<span
 					className="mono"
 					style={{
 						fontSize: "var(--mono-size)",
 						color: badgeColor,
 						borderWidth: "var(--rule-width)",
 						borderStyle: "solid",
 						borderColor: "var(--rule)",
 						padding: "calc(var(--space-base) / 4) calc(var(--space-base) / 2)",
 						borderRadius: "var(--radius-control)",
 						letterSpacing: "0.06em",
 						textTransform: "uppercase",
+						whiteSpace: "nowrap",
+						flexShrink: 0,
 					}}
 				>
 					{activeBanner.title}
 				</span>
 				<span
 					style={{
 						color: "var(--ink-muted)",
 						fontSize: "var(--mono-size)",
 						fontFamily: "var(--font-mono)",
 					}}
 				>
 					{activeBanner.content}
 				</span>
 				{activeBanner.cta && (
 					<Link
 						href={activeBanner.cta.href}
 						onClick={handleClick}
 						style={{
 							color: "var(--ink)",
 							fontFamily: "var(--font-mono)",
 							fontSize: "var(--mono-size)",
