import { chromium } from "@playwright/test";

const run = async () => {
	const browser = await chromium.launch();
	const page = await browser.newPage({
		viewport: { width: 1440, height: 900 },
	});
	await page.goto("http://localhost:3964/", { waitUntil: "networkidle" });
	await page.waitForTimeout(2500);
	const anchor = page.locator("#chapter-04");
	await anchor.scrollIntoViewIfNeeded();
	await page.waitForTimeout(1800);
	await page.screenshot({ path: "/tmp/shot-ch4.png" });
	// Click the canvas center to select a node, then shoot the details panel.
	const canvas = page.locator("#chapter-04 canvas");
	await canvas.click({ position: { x: 120, y: 220 } });
	await page.waitForTimeout(600);
	await page.screenshot({ path: "/tmp/shot-ch4-click.png" });
	await browser.close();
	console.log("done");
};

run();

