export const GRAPH_COL_X = 200;
export const GRAPH_ROW_H = 30;

export interface PlacedNode extends ConversionGraphNode {
	x: number;
	y: number;
	w: number;
	h: number;
}

input.newString:
/**
 * Topmost-first hit test over placed boxes. Later nodes draw over earlier
 * ones, so reverse order matches what the eye sees.
 */
export function hitTestNode(
	nodes: PlacedNode[],
	px: number,
	py: number,
): PlacedNode | undefined {
	for (let i = nodes.length - 1; i >= 0; i--) {
		const node = nodes[i];
		if (!node) continue;
		if (
			px >= node.x &&
			px <= node.x + node.w &&
			py >= node.y &&
			py <= node.y + node.h
		) {
			return node;
		}
	}
	return undefined;
}

export interface FitTransform {
	x: number;
	y: number;
	k: number;
}

/**
 * Fit a placed graph inside a viewport with padding on all sides,
 * preserving aspect (one scale factor, never upscale past 1:1, never
 * below 0.3). Pure, so the no-clipping guarantee is unit-testable across
 * sources and sizes: every mapped box must land inside the viewport.
 */
export function fitTransform(
	nodes: PlacedNode[],
	viewportW: number,
	viewportH: number,
	pad = 24,
): FitTransform {
	if (nodes.length === 0 || viewportW <= 0 || viewportH <= 0) {
		return { x: 0, y: 0, k: 1 };
	}
	const minX = Math.min(...nodes.map((n) => n.x));
	const maxX = Math.max(...nodes.map((n) => n.x + n.w));
	const minY = Math.min(...nodes.map((n) => n.y));
	const maxY = Math.max(...nodes.map((n) => n.y + n.h));
	const k = Math.max(
		0.3,
		Math.min(
			1,
			(viewportW - pad * 2) / Math.max(1, maxX - minX),
			(viewportH - pad * 2) / Math.max(1, maxY - minY),
		),
	);
	return {
		k,
		x: pad - minX * k + (viewportW - pad * 2 - (maxX - minX) * k) / 2,
		y: viewportH / 2 - ((minY + maxY) / 2) * k,
	};
}

